BANK = []

def q(domain, subcategory, text, choices, correct, explanation, point, terms, reference, difficulty='basic'):
    """Each choice is an independently authored (text, explanation) pair."""
    ids = list('ABCD')[:len(choices)]
    reference_keys = reference.split()
    if subcategory == 'リソースロック':
        reference_keys.append('lock-details')
    if 'ポリシー効果' in text:
        reference_keys.append('effects')
    BANK.append({
        'id': f'Q{len(BANK) + 1:03d}', 'version': 1, 'domain': domain,
        'subcategory': subcategory, 'difficulty': difficulty,
        'questionType': 'multiple' if len(correct) > 1 else 'single',
        'questionText': text,
        'options': [{'id': i, 'text': c[0]} for i, c in zip(ids, choices)],
        'correctOptionIds': list(correct), 'explanation': explanation,
        'optionExplanations': {i: c[1] for i, c in zip(ids, choices)},
        'keyPoint': point, 'relatedTermIds': terms.split(),
        'referenceUrls': [REFS[k] for k in reference_keys],
        'originType': 'original', 'license': 'CC-BY-4.0', 'lastVerifiedAt': '2026-10-10',
    })

